//! LCD controller pad functions of the SWM341 pin matrix.
//!
//! Generated by `scripts/gen_pin_func.py` from the vendor header
//! `SWM341_port.h` -- do not edit by hand.
//!
//! Each `Pin{n}Func` enumerates the LCD functions selectable on pin `{n}` of its
//! bank; the numeric value of every variant is the 4-bit code written into
//! `PORTx.FUNC0/FUNC1`. `LCD_Rn`/`LCD_Gn`/`LCD_Bn` are the parallel data lines,
//! `LCD_VSYNC`/`LCD_HSYNC`/`LCD_DEN`/`LCD_DCLK` the RGB sync signals and
//! `LCD_CS`/`LCD_RS`/`LCD_WR`/`LCD_RD` the MPU-interface strobes -- some pads
//! carry both an RGB and an MPU spelling of the same line at the same code.
//! Code `0` (generic GPIO) is omitted. The variants are the type-checked
//! arguments used by [`crate::lcdc::Lcd::new_with_pins`] (through the
//! `LcdPins` bundle) and are also usable with [`crate::gpio::Flex::set_func`].


/// Generate the per-pin `Pin{n}Func` enums for one bank module.
///
/// Each entry is `PinType => Enum { Variant = func_code, ... }`; the macro
/// writes the `#[repr(u8)]` enum plus its `PinFunc` / `PinFuncOf` impls.
/// The codes go into the `PinFunc::value` match instead of enum
/// discriminants: one pad often carries several names for the same line
/// (`LCD_CS` and `LCD_VSYNC` on PB2 are both code `6`), and two variants
/// with the same discriminant do not compile.
macro_rules! pad_funcs {
    ( $( $pin_ty:ident => $enum:ident { $( $var:ident = $val:literal ),* $(,)? } ),* $(,)? ) => {
        $(
            #[derive(Clone, Copy, PartialEq, Eq, Debug)]
            #[repr(u8)]
            pub enum $enum {
                $( $var, )*
            }
            impl crate::gpio::PinFunc for $enum {
                #[inline]
                fn value(self) -> u8 {
                    match self {
                        $( $enum::$var => $val, )*
                    }
                }
            }
            impl crate::gpio::PinFuncOf<crate::gpio::$pin_ty> for $enum {}
        )*
    };
}

pub mod a {
    pad_funcs! {
        PA0 => Pin0Func { LcdB7 = 4 },
        PA1 => Pin1Func { LcdB3 = 4 },
        PA2 => Pin2Func { LcdB4 = 4 },
        PA3 => Pin3Func { LcdB6 = 2 },
        PA4 => Pin4Func { LcdB5 = 2 },
        PA9 => Pin9Func { LcdB5 = 2 },
        PA10 => Pin10Func { LcdB6 = 5 },
        PA11 => Pin11Func { LcdB7 = 4 },
        PA12 => Pin12Func { LcdG0 = 4 },
        PA13 => Pin13Func { LcdG1 = 4 },
        PA14 => Pin14Func { LcdG2 = 2 },
        PA15 => Pin15Func { LcdG3 = 2 },
    }
}

